#include <string.h>
#include <stdio.h>

void foo(char *str) {
    char buf[64];
    size_t len = strlen(str);

    if (len >= sizeof(buf)) {
        fprintf(stderr, "Input string is too long.\n");
        return;
    }

    strncpy(buf, str, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
}

